    #[geam_macros::custom(input = EnvelopeInput)]
    enum Envelope<Item> {
        Single(Value<Item>),
        Many(Vec<Value<Item>>),
    }

    #[geam_macros::function]
    fn wrap<Item>(value: Value<Item>) -> Envelope<Item> {
        Envelope::Single(value)
    }

    #[geam_macros::function]
    fn wrap_many<Item>(value: Value<Item>) -> Envelope<Item> {
        Envelope::Many(vec![value])
    }

    #[geam_macros::function]
    fn unwrap<Item>(value: EnvelopeInput<Item>) -> Value<Item> {
        match value {
            EnvelopeInput::Single(value) => value,
            EnvelopeInput::Many(values) => values.get(0).expect("fixture supplies a value"),
        }
    }
